import sys

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        print("ERROR: 0")
        print("INFO: 0")
        print("WARNING: 0")
        return

    n = int(data[0])

    error_count = 0
    info_count = 0
    warning_count = 0

    for i in range(1, n + 1):
        if i < len(data):
            line = data[i]
            if "ERROR" in line:
                error_count += 1
            if "INFO" in line:
                info_count += 1
            if "WARNING" in line:
                warning_count += 1

    print(f"ERROR: {error_count}")
    print(f"INFO: {info_count}")
    print(f"WARNING: {warning_count}")

if __name__ == "__main__":
    main()
